result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/units.py", "content": """"Unit-aware numeric grading.

Converts both quantities to their base unit (m, g, s), then compares
with abs(a - b) <= rtol * abs(b). Incompatible dimensions grade as
incorrect (False); unknown or missing units raise ValueError.
"""

_LENGTH = {'m': 1.0, 'cm': 0.01, 'mm': 0.001, 'km': 1000.0}
_MASS = {'g': 1.0, 'kg': 1000.0, 'mg': 0.001}
_TIME = {'s': 1.0, 'min': 60.0, 'h': 3600.0}

_TABLES = (_LENGTH, _MASS, _TIME)


def parse(quantity):
    """Parse '3 cm' -> (3.0, factor-to-base, dimension).

    Raises ValueError on missing or unknown units.
    """
    parts = quantity.strip().split()
    if len(parts) != 2:
        raise ValueError(f"expected '<number> <unit>', got {quantity!r}")
    value_text, unit = parts
    try:
        value = float(value_text)
    except ValueError:
        raise ValueError(f"invalid number in {quantity!r}")
    for table, dim in zip(_TABLES, ('length', 'mass', 'time')):
        if unit in table:
            return value, table[unit], dim
    raise ValueError(f"unknown unit {unit!r}")


def to_base(quantity):
    """Parse a quantity and return (value_in_base_units, dimension)."""
    value, factor, dim = parse(quantity)
    return value * factor, dim


def grade(student, correct, rtol=0.0):
    """True iff student matches correct within relative tolerance rtol."""
    a, a_dim = to_base(student)
    b, b_dim = to_base(correct)
    if a_dim != b_dim:
        return False
    return abs(a - b) <= rtol * abs(b)
